'use strict';
let learningProgress={};try{learningProgress=JSON.parse(localStorage.getItem('spotmatch-learning-v1')||'{}')||{}}catch{}
let activeLearningCourse=null,learningState=null;
const visualCourseHome=home;
function persistLearning(){try{localStorage.setItem('spotmatch-learning-v1',JSON.stringify(learningProgress))}catch{}}
function bindLibraryNav(){document.querySelector('#libraryNav').onclick=()=>{activeLearningCourse=null;libraryHome()};}
function courseCompleted(key){return Object.values(learningProgress[key]||{}).filter(x=>x.complete).length}
function libraryHome(){activeLearningCourse=null;const visualDone=Object.values(saved).filter(x=>x.complete).length;app.innerHTML=`<section class="hero library-hero"><div><span class="eyebrow pill">BEFORE THE FIRST WORD</span><h1>Small discoveries.<br><em>Many ways to grow.</em></h1><p>Seven gentle courses for pictures, events, stories, meaning, language, and speech sounds. Three courses require an adult throughout. No generated voice or time pressure.</p><div class="hero-actions"><a href="#course-library" class="primary library-link">Explore the courses ↓</a><span class="micro">145 games · Choose a comfortable start</span></div></div><div class="library-art" aria-hidden="true"><div class="library-picture">${pictureIcon('sprout')}</div><div class="library-picture">${pictureIcon('book')}</div><div class="library-picture">${pictureIcon('basket')}</div><span class="library-spark">✧</span></div></section><section class="intro"><div><b>OUR APPROACH</b><p>One clear skill, small steps, and room to repeat. Use a demonstration and follow the child’s interests and access needs.</p></div><div><b>BEFORE AND ALONGSIDE READING</b><p>These are learning opportunities, not a readiness test. Children do not need to finish these courses before receiving reading instruction or communication support.</p></div></section><section id="course-library"><div class="section-head"><div><span class="eyebrow">CHOOSE YOUR LEARNING JOURNEY</span><h2>Seven paths. A comfortable pace.</h2></div></div><div class="library-grid"><button class="library-card" data-course="visual"><div class="library-card-art" style="background:#e8eedd">${art({shape:0,color:0})}</div><span class="eyebrow">COURSE 01 · 25 GAMES</span><h2>Visual Differentiation</h2><p>Notice shapes, patterns, positions, and the little details that make pictures alike or different.</p><span class="library-card-foot">${visualDone} of 25 practiced <b>Explore →</b></span></button>${Object.entries(newCourseInfo).map(([key,c],i)=>`<button class="library-card" data-course="${key}"><div class="library-card-art" style="background:${c.color}">${pictureIcon(c.icon||(key==='events'?'wateringcan':key==='stories'?'book':'basket'))}</div><span class="eyebrow">COURSE 0${i+2} · 20 GAMES</span><h2>${c.title}</h2>${c.adultRequired?'<span class="adult-badge">Adult support required</span>':''}<p>${c.subtitle}. ${c.goal}</p><span class="library-card-foot">${courseCompleted(key)} of 20 practiced <b>Explore →</b></span></button>`).join('')}</div><p class="note">Progress stays in this browser. Choose by the child’s needs, not their diagnosis. A grown-up can demonstrate any activity.</p></section>`;document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>openLearningCourse(b.dataset.course));bindLibraryNav();document.querySelector('#courseNav').onclick=()=>document.querySelector('#course-library').scrollIntoView({behavior:'smooth'});document.querySelector('#brand').onclick=e=>{e.preventDefault();libraryHome()};document.querySelector('#guideNav').onclick=()=>showLearningGuide(null);window.scrollTo({top:0,behavior:'instant'});}
function openLearningCourse(key){activeLearningCourse=key;if(key==='visual'){visualCourseHome();bindLibraryNav();document.querySelector('#guideNav').onclick=guide;return;}renderLearningCourse();}
home=function(){if(activeLearningCourse==='visual'){visualCourseHome();bindLibraryNav();document.querySelector('#guideNav').onclick=guide;}else if(activeLearningCourse){renderLearningCourse()}else libraryHome()};
function renderLearningCourse(){const key=activeLearningCourse,c=newCourseInfo[key],done=courseCompleted(key);app.innerHTML=`<div class="play-top"><button class="back" id="toLibrary">← All courses</button><span class="micro">20 GAMES · NO AUDIO · AT YOUR OWN PACE</span></div>${c.adultRequired?adultSupportBanner(key):''}<section class="course-hero"><div><span class="eyebrow pill">${c.subtitle.toUpperCase()}</span><h1>${c.title}<span class="course-title-dot">.</span></h1><p>${c.goal}</p><button class="primary" id="startLearning">${c.adultRequired?(done?'Continue with an adult':'Start with an adult'):(done?'Continue the course':'Start the course')} →</button></div><div class="course-hero-art" style="background:${c.color}" aria-hidden="true">${pictureIcon(c.icon||(key==='events'?'sprout':key==='stories'?'book':'basket'))}</div></section><section class="intro"><div><b>THE CHALLENGE</b><p>${c.problem}</p></div><div><b>OUR GOAL</b><p>${c.goal}</p></div></section><section class="skill-explainer"><div><span class="eyebrow">WHAT WE PRACTICE</span><h2>${c.subtitle}</h2><p>${c.practice}</p><p>${c.limit}</p></div><div class="everyday-card"><b>Who might find it useful?</b><p>${c.who}</p><p class="micro">A wrong answer may reflect unfamiliar images, unclear instructions, motor access, vision, or overload. It is not a diagnosis.</p></div></section><section class="course-evidence"><b>Research-informed, individually adapted</b><p>${c.research} <a href="${c.source}" target="_blank" rel="noopener">Read the source ↗</a></p><button class="secondary" id="learningGuide">Grown-up guide & adaptations ↗</button></section><section id="journey"><div class="section-head"><div><span class="eyebrow">THE LEARNING PATH</span><h2>Twenty little discoveries.</h2><p>The order is suggested. Repeat or skip a game to suit the child.</p></div><div class="progress-label">${done} of 20 practiced<div class="progress-track"><i style="width:${done*5}%"></i></div></div></div>${[0,10].map(start=>`<div class="path-label"><span>${start?'11—20':'01—10'}</span>${start?'Connect, apply, and explore':'Begin with familiar ideas'}</div><div class="grid">${c.games.slice(start,start+10).map((d,j)=>{const i=start+j;return `<button class="course-card ${learningProgress[key]?.[i]?.complete?'completed':''}" data-learning-game="${i}"><div class="thumb" style="--tint:${c.color}">${learnPicture(key==='events'?{scene:i,stage:1}:key==='stories'?{story:i,stage:1}:d.object)}</div><span class="card-num">GAME ${String(i+1).padStart(2,'0')}</span><h3>${d.title}</h3><p>${gameLearningLabel(key,i)}</p><div class="card-bottom"><span>${learningProgress[key]?.[i]?.complete?'✓ Practiced':'3 practice rounds'}</span><span aria-hidden="true">↗</span></div></button>`}).join('')}</div>`).join('')}<p class="note">Completing a game records practice, not mastery. Try the real-world exercise and unfamiliar examples to check transfer.</p></section>`;document.querySelector('#toLibrary').onclick=libraryHome;document.querySelector('#startLearning').onclick=()=>learningIntro(Math.max(0,c.games.findIndex((_,i)=>!learningProgress[key]?.[i]?.complete)));document.querySelectorAll('[data-learning-game]').forEach(b=>b.onclick=()=>learningIntro(+b.dataset.learningGame));document.querySelector('#learningGuide').onclick=()=>showLearningGuide(key);document.querySelector('#guideNav').onclick=()=>showLearningGuide(key);document.querySelector('#courseNav').onclick=()=>document.querySelector('#journey').scrollIntoView({behavior:'smooth'});document.querySelector('#brand').onclick=e=>{e.preventDefault();libraryHome()};bindLibraryNav();window.scrollTo({top:0,behavior:'instant'});}
function gameLearningLabel(key,i){if(newCourseInfo[key]?.adultRequired)return newCourseInfo[key].games[i].skill;if(key==='events')return{order2:'Put two events in order.',first:'Find the beginning.',last:'Find the ending.',missing:'Choose the missing action.',order3:'Build a three-event sequence.',repair:'Repair a mixed-up sequence.'}[eventRoutines[i].mode];if(key==='stories')return i<4?'Notice the character’s goal.':i<8?'Find the problem and a helpful action.':i<12?'Connect tools with a solution.':i<16?'Connect an action with its outcome.':'Build the connected picture story.';return{representation:'Recognize a different drawing.',partner:'Connect objects that work together.',use:'Choose an object for a purpose.',location:'Connect an object with a scene.',combine:'Choose two items for the scene.'}[meaningGames[i].mode];}
function showLearningGuide(key){const c=key?newCourseInfo[key]:null,d=document.createElement('dialog');d.className='learning-guide';d.innerHTML=`<button class="close" aria-label="Close guide">×</button><span class="eyebrow">FOR GROWN-UPS</span><h2>${c?c.title:'Learning before reading'}</h2><p>${c?c.problem:'Use the courses to explore specific learning needs. They are not a test of intelligence, reading readiness, or eligibility for communication support.'}</p><p><b>What we develop.</b> ${c?c.goal:'Visual comparisons, meaningful event order, story relationships, and picture meanings. Each course has its own description and practical exercises.'}</p><p><b>Who might benefit.</b> ${c?c.who:'Some children with developmental delay, intellectual disability, autism, language difficulties, or complex communication needs may find selected activities useful. These are possibilities, not evidence that the apps treat a diagnosis.'}</p>${c?.adultRequired?adultSupportBanner(key):''}<p><b>Language access.</b> Demonstrate the task. Use speech, sign, gesture, or the child’s established AAC system to explain the idea as appropriate. Silent pictures do not automatically teach vocabulary, grammar, or the meanings of abstract questions. Keep AAC available; never require these games before communication support.</p><p><b>Adjust the activity.</b> Begin with a few comfortable minutes. Allow pointing with partner-assisted selection if tapping is difficult. Buttons support keyboard Tab and Enter/Space. There are no time limits or compulsory dragging. Low vision or cerebral visual impairment may need specialist advice. No independent eye-gaze access is provided.</p><p><b>Check understanding.</b> Use a real object or act out the routine. Later try a new example and see whether less help is needed. Screen completion alone is not mastery. Printed descriptions are for adult support; the child can respond to pictures.</p>${c?`<p><b>Limits.</b> ${c.limit} ${c.research}</p><p><a href="${c.source}" target="_blank" rel="noopener">Research or professional guidance ↗</a></p>`:''}<p><b>Reading.</b> These activities can begin before reading and continue alongside it. They are not a treatment for dyslexia and must not delay language, literacy, or communication instruction.</p><button class="secondary" id="resetLearning">Reset ${c?'this course’s':'the six additional courses’'} progress</button>`;document.body.append(d);d.querySelector('.close').onclick=()=>{d.close();d.remove()};d.querySelector('#resetLearning').onclick=()=>{if(confirm('Clear this course progress on this device?')){if(key)delete learningProgress[key];else learningProgress={};persistLearning();d.close();d.remove();home()}};d.showModal();}
function learningShell(body,keepScroll=false){app.innerHTML=`<div class="play-top"><button class="back" id="learningBack">← Back to ${newCourseInfo[activeLearningCourse].title}</button><span class="micro">GAME ${learningState.index+1} OF 20</span></div><section class="game-wrap learning-game">${newCourseInfo[activeLearningCourse]?.adultRequired?adultSupportBanner(activeLearningCourse):''}${body}</section>`;document.querySelector('#learningBack').onclick=renderLearningCourse;document.querySelector('#guideNav').onclick=()=>showLearningGuide(activeLearningCourse);document.querySelector('#courseNav').onclick=renderLearningCourse;bindLibraryNav();if(!keepScroll)window.scrollTo({top:0,behavior:'instant'});}
function learningIntro(index){if(newCourseInfo[activeLearningCourse]?.adultRequired){adultIntro(index);return}learningState={index,round:0,independent:0,hints:0,seed:Math.floor(Math.random()*3)};const key=activeLearningCourse,d=newCourseInfo[key].games[index];let model='';if(key==='events')model=d.steps.map((_,stage)=>learnPicture({scene:index,stage}));else if(key==='stories')model=[0,1,2,3].map(stage=>learnPicture({story:index,stage}));else model=d.mode==='representation'?[pictureIcon(d.object,0),pictureIcon(d.object,3)]:d.mode==='location'?[pictureIcon(d.object),learnPicture({location:d.location})]:d.mode==='combine'?[learnPicture({location:d.location}),pictureIcon(d.object),pictureIcon(d.partner)]:[pictureIcon(d.object),pictureIcon(d.partner)];learningShell(`<span class="eyebrow">LOOK, EXPLORE, THEN TRY</span><h1>${d.title}</h1><p>${gameLearningLabel(key,index)}</p><div class="game-stage"><div class="story-strip demo-story">${model.map((svg,i)=>`<div class="story-frame">${svg}<span class="frame-dot" aria-hidden="true">${i+1}</span></div>${i<model.length-1?`<span class="strip-arrow" aria-hidden="true">${key==='meaning'?(d.mode==='combine'?'+':'↔'):'→'}</span>`:''}`).join('')}</div><p>${key==='events'?'Look at how the events connect.':key==='stories'?d.explanation:d.explanation}</p><button class="primary" id="learningBegin">Let’s try →</button></div><div class="learning-note"><b>Try it away from the screen.</b> ${d.exercise}</div>`);document.querySelector('#learningBegin').onclick=learningPlay;}
function learningData(key,index,round,seed){
 const variant=(round+seed)%3,d=newCourseInfo[key].games[index];let task={variant,selected:[],swapping:null};
 const scene=stage=>({scene:index,stage}),story=stage=>({story:index,stage});
 if(key==='events'){
  task.mode=d.mode;task.prompt={order2:'Tap the two pictures in the order they happen.',first:'Which picture shows the beginning?',last:'Which picture shows the ending?',missing:'Which picture belongs in the middle?',order3:'Tap the pictures to build the event sequence.',repair:'Tap two positions to swap them. Put the events in order.'}[d.mode];
  if(d.mode==='order2'){const stages=index===3?[1,2]:[0,2];task.options=shuffle(stages.map(s=>({id:s,picture:scene(s)})));task.answer=stages;task.reference=[];}
  else if(d.mode==='order3'||d.mode==='repair'){task.options=shuffle([0,1,2].map(s=>({id:s,picture:scene(s)})));task.answer=[0,1,2];task.reference=[];if(d.mode==='repair')task.selected=round%2?[2,1,0]:[1,0,2];}
  else{task.options=shuffle([0,1,2].map(s=>({id:s,picture:scene(s)})));task.answer=[d.mode==='first'?0:d.mode==='last'?2:1];task.reference=d.mode==='missing'?[scene(0),null,scene(2)]:[];}
  task.explanation=d.steps.map(s=>s.text).join(' ');
 }
 if(key==='stories'){
  const question=index>=16&&round===2?'order':round===0?(index<4?'goal':index<8?'problem':index<12?'tool':'outcome'):round===1?'tool':'outcome';
  task.mode=question==='order'?'order4':'choice';task.prompt={goal:'What is the character trying to get or do?',problem:'Which picture shows the problem?',tool:'Which object could help in this story?',outcome:'Which picture shows the outcome?',order:'Put the four story pictures in order.'}[question];
  task.reference=question==='order'?[]:question==='goal'?[story(0)]:question==='problem'?[story(0),story(1)]:question==='tool'?[story(0),story(1)]:[story(1),story(2)];
  if(question==='order'){task.options=shuffle([0,1,2,3].map(s=>({id:s,picture:story(s)})));task.answer=[0,1,2,3];}
  else{const answer=question==='goal'?d.goal:question==='problem'?d.obstacle:question==='tool'?d.tool:d.outcome;let pool=question==='tool'?['brush','pitcher','bridge','tape','wheel','cloth','lamp','wateringcan','hat','blanket','ladder','tray','shovel','clip','grain','coat','flashlight']:['car','apple','shoe','umbrella','ball','book','flower','bed','basket','fullcup','emptybowl','gift','tower','rain','tree','sun','rock','clock','dark'];pool=shuffle(pool.filter(x=>x!==answer));task.options=shuffle([{id:answer,picture:answer},...pool.slice(0,2).map(id=>({id,picture:id}))]);task.answer=[answer];}
  task.explanation=d.explanation;
 }
 if(key==='meaning'){
  task.mode=d.mode==='combine'?'combine':'choice';const object=d.object;
  const pool=['cup','shoe','ball','book','spoon','brush','key','wateringcan','umbrella','coat','tray','bed','chair','flower','car','hat','bowl','blanket','basket'];
  if(d.mode==='combine'){task.prompt='Choose both objects shown for this scene, then check.';task.reference=[{location:d.location},object,d.partner];task.answer=[object,d.partner];let wrong=shuffle(pool.filter(x=>!task.answer.includes(x))).slice(0,2);task.options=shuffle([...task.answer,...wrong].map(id=>({id,picture:id})));}
  else if(d.mode==='representation'){task.prompt='Find the same object in a different drawing style.';task.reference=[object];task.referenceVariant=3;task.answer=[object];task.options=shuffle([object,...shuffle(pool.filter(x=>x!==object)).slice(0,2)].map(id=>({id,picture:id})));}
  else if(d.mode==='partner'){task.prompt='Which object works with this one in our example?';task.reference=[object];task.answer=[d.partner];task.options=shuffle([d.partner,...shuffle(pool.filter(x=>x!==d.partner&&x!==object)).slice(0,2)].map(id=>({id,picture:id})));}
  else if(d.mode==='use'){task.prompt='Which object could help with the pictured activity?';task.reference=[d.partner];task.answer=[object];task.options=shuffle([object,...shuffle(pool.filter(x=>x!==object&&x!==d.partner)).slice(0,2)].map(id=>({id,picture:id})));}
  else{task.prompt='Choose the scene shown for this object in our example.';task.reference=[object];task.answer=[d.location];let locations=shuffle(['kitchen','garden','bedroom','outside','bathroom','playroom','desk','doorway'].filter(x=>x!==d.location));task.options=shuffle([d.location,...locations.slice(0,2)].map(id=>({id,picture:{location:id}})));}
  task.explanation=d.explanation;
 }
 return task;
}
function learningPlay(){Object.assign(learningState,{missed:false,hinted:false,answered:false},learningData(activeLearningCourse,learningState.index,learningState.round,learningState.seed));renderLearningTask('Take your time.');window.scrollTo({top:0,behavior:'instant'});}
function isSequenceTask(){return ['order2','order3','order4','repair'].includes(learningState.mode)}
function learningTaskBody(){const s=learningState,sequence=isSequenceTask();let ref='';if(s.reference?.length)ref=`<div class="story-strip reference-strip">${s.reference.map(p=>p?`<div class="story-frame">${learnPicture(p,s.referenceVariant??s.variant)}</div>`:'<div class="story-frame missing-frame" aria-label="Missing event">?</div>').join(`<span class="strip-arrow" aria-hidden="true">${activeLearningCourse==='meaning'?(s.mode==='combine'?'+':'↔'):'→'}</span>`)}</div>`;
 if(sequence){ref+=`<div class="sequence-slots" role="group" aria-label="Your event order">${s.answer.map((_,pos)=>{const id=s.selected[pos],option=s.options.find(o=>o.id===id);return `<button class="sequence-slot ${s.swapping===pos?'selected':''}" data-slot="${pos}" aria-label="Position ${pos+1}${option?', occupied':', empty'}" ${s.answered?'disabled':''}>${option?learnPicture(option.picture,s.variant):'<span aria-hidden="true">＋</span>'}<small>${pos+1}</small></button>`}).join('')}</div>`;}
 return ref+`<div class="learning-options ${s.options.length===4?'four-options':''}">${s.options.map((o,i)=>`<button class="learning-option ${s.selected.includes(o.id)?'selected':''} ${s.hinted&&s.answer.includes(o.id)?'hinted':''} ${s.answered&&s.answer.includes(o.id)?'correct':''}" data-learning-choice="${i}" aria-label="${sequence?'Add':'Choose'} picture ${i+1}" aria-pressed="${s.selected.includes(o.id)}" ${s.answered||(sequence&&s.selected.includes(o.id))?'disabled':''}>${learnPicture(o.picture,s.variant)}${s.selected.includes(o.id)?'<span class="selected-check" aria-hidden="true">✓</span>':''}</button>`).join('')}</div>`;
}
function renderLearningTask(message){const focused=document.activeElement;let restore=null;if(focused){if(focused.dataset.learningChoice!==undefined)restore=`[data-learning-choice="${focused.dataset.learningChoice}"]`;else if(focused.dataset.slot!==undefined)restore=`[data-slot="${focused.dataset.slot}"]`;else if(['learningCheck','learningHint','learningClear'].includes(focused.id))restore='#'+focused.id;}const s=learningState,d=newCourseInfo[activeLearningCourse].games[s.index];learningShell(`<span class="eyebrow">${newCourseInfo[activeLearningCourse].subtitle.toUpperCase()}</span><h1>${d.title}</h1><p>${s.prompt}</p><div class="game-stage learning-stage">${learningTaskBody()}<div class="feedback" role="status" aria-live="polite">${message}</div><div class="game-controls"><button class="secondary" id="learningHint" ${s.answered?'hidden':''}>Show me a clue</button>${isSequenceTask()||s.mode==='combine'?`<button class="secondary" id="learningClear" ${s.answered?'hidden':''}>Start this round again ↶</button><button class="primary" id="learningCheck" ${s.answered?'hidden':''}>Check ✓</button>`:''}<button class="primary" id="learningNext" ${s.answered?'':'hidden'}>${s.round===2?'Finish game →':'Next round →'}</button></div>${s.answered?`<p class="outcome-explanation">${s.explanation}</p>`:''}</div><div class="play-top"><span class="micro">Round ${s.round+1} of 3</span><div class="round-dots" aria-hidden="true">${[0,1,2].map(i=>`<i class="${i<s.round?'done':i===s.round?'current':''}"></i>`).join('')}</div><button class="back" id="learningModel">See example ↗</button></div><details class="learning-note"><summary>Try it with real objects</summary><p>${d.exercise}</p></details>`,true);
 document.querySelectorAll('[data-learning-choice]').forEach(b=>b.onclick=()=>learningChoose(+b.dataset.learningChoice));document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>learningSlot(+b.dataset.slot));document.querySelector('#learningHint').onclick=learningHint;const check=document.querySelector('#learningCheck');if(check)check.onclick=learningCheck;const clear=document.querySelector('#learningClear');if(clear)clear.onclick=()=>{s.selected=s.mode==='repair'?[1,0,2]:[];s.swapping=null;renderLearningTask('A fresh arrangement. Try again.');};document.querySelector('#learningNext').onclick=()=>{if(!s.answered)return;s.round++;s.round<3?learningPlay():learningFinish()};document.querySelector('#learningModel').onclick=learningExample;if(restore){const b=document.querySelector(restore);if(b&&!b.disabled)b.focus();else{const next=document.querySelector('[data-learning-choice]:not(:disabled)');if(next)next.focus();}}
}
function learningChoose(i){const s=learningState;if(s.answered)return;const o=s.options[i];if(isSequenceTask()){if(s.mode==='repair'){renderLearningTask('Tap two pictures in your order above to swap them.');return}if(!s.selected.includes(o.id)&&s.selected.length<s.answer.length)s.selected.push(o.id);renderLearningTask('Check your order when every space is filled.');return}if(s.mode==='combine'){if(s.selected.includes(o.id))s.selected=s.selected.filter(id=>id!==o.id);else s.selected.push(o.id);renderLearningTask('Choose the two items, then check.');return}if(o.id===s.answer[0])learningSuccess();else{s.missed=true;renderLearningTask('Look again at the picture and the example. Another choice fits this story.');}}
function learningSlot(pos){const s=learningState;if(s.answered)return;if(s.mode==='repair'){if(s.swapping===null){s.swapping=pos;renderLearningTask('Now tap the other position to swap.');}else{[s.selected[pos],s.selected[s.swapping]]=[s.selected[s.swapping],s.selected[pos]];s.swapping=null;renderLearningTask('The pictures swapped. Check the event order.');}}else if(s.selected[pos]!==undefined){s.selected.splice(pos,1);renderLearningTask('That picture returned below. Choose the next event.');}}
function learningCheck(){const s=learningState;if(s.answered)return;const matches=s.mode==='combine'?s.selected.length===s.answer.length&&s.answer.every(id=>s.selected.includes(id)):s.selected.length===s.answer.length&&s.answer.every((id,i)=>s.selected[i]===id);if(matches)learningSuccess();else{s.missed=true;renderLearningTask(isSequenceTask()?'The order needs another look. Compare the beginning, action, and ending.':'Check which two items are shown for this scene.');}}
function learningHint(){const s=learningState;if(s.answered)return;if(!s.hinted){s.hinted=true;s.hints++;}if(isSequenceTask()){s.selected=[...s.answer];s.swapping=null;renderLearningTask('Here is the connected order. Look at each event, then check.');}else renderLearningTask('The outlined pictures fit this example.');}
function learningExample(){const s=learningState;if(!s.answered&&!s.hinted){s.hinted=true;s.hints++;}const d=newCourseInfo[activeLearningCourse].games[s.index],dialog=document.createElement('dialog');let sequence=activeLearningCourse==='events'?d.steps.map((_,stage)=>({scene:s.index,stage})):activeLearningCourse==='stories'?[0,1,2,3].map(stage=>({story:s.index,stage})):d.mode==='location'?[d.object,{location:d.location}]:d.mode==='combine'?[{location:d.location},d.object,d.partner]:[d.object,d.partner];dialog.innerHTML=`<button class="close" aria-label="Close example">×</button><h2>${d.title}</h2><div class="story-strip">${sequence.map(p=>`<div class="story-frame">${learnPicture(p)}</div>`).join('<span class="strip-arrow">→</span>')}</div><p>${activeLearningCourse==='events'?d.steps.map(x=>x.text).join(' '):d.explanation}</p>`;document.body.append(dialog);dialog.querySelector('button').onclick=()=>{dialog.close();dialog.remove();if(!s.answered)renderLearningTask('Compare the pictures with the example you explored.')};dialog.showModal();}
function learningSuccess(){const s=learningState;if(s.answered)return;s.answered=true;if(!s.missed&&!s.hinted)s.independent++;renderLearningTask('✓ You connected the pictures!');document.querySelector('#learningNext').focus();}
function learningFinish(){const s=learningState,key=activeLearningCourse,d=newCourseInfo[key].games[s.index];learningProgress[key]??={};learningProgress[key][s.index]={complete:true,independent:s.independent,hints:s.hints,date:new Date().toISOString()};persistLearning();learningShell(`<span class="eyebrow">A LITTLE DISCOVERY, WELL DONE</span><div class="success-icon" aria-hidden="true">✳</div><h1>You explored ${d.title.toLowerCase()}!</h1><p>Three rounds of connecting pictures and ideas.</p><div class="completion-stat"><div><b>3</b><span>rounds practiced</span></div><div><b>${s.independent}</b><span>rounds without retries or hints</span></div></div><p class="micro">Practice completed · This is not a mastery assessment.</p><div class="game-controls"><button class="secondary" id="learningAgain">Play again</button><button class="primary" id="learningContinue">${s.index<19?'Next game →':'Back to the course →'}</button></div><div class="learning-note"><b>Now try it away from the screen.</b> ${d.exercise}</div>`);document.querySelector('#learningAgain').onclick=()=>learningIntro(s.index);document.querySelector('#learningContinue').onclick=()=>s.index<19?learningIntro(s.index+1):renderLearningCourse();}
libraryHome();
